route-task.ps1
行号问题类型描述修复代码18-29protocol任务分类使用连续 if，后面的低风险类型会覆盖前面的高风险类型。例如同时命中“安全”和“实现/复杂”时，可能从 security_audit/L4 降到 complex_code/L2。<pre><code># 替换 Classify task type 这一整段
$taskType = "simple_edit"
$riskLevel = "L1"
if ($Task -match '(?i)删除|重置|清空|production|生产|delete.*all|wipe') {
$taskType = "destructive_or_production"
$riskLevel = "L5"
}
elseif ($Task -match '(?i)密钥|远程|部署|SSH|deploy|remote|安全|审计|漏洞|注入|token|secret|凭证|security|audit|vuln') {
$taskType = "security_audit"
$riskLevel = "L4"
}
elseif ($Task -match '(?i)hook|门禁|gate|stop-gate|block-dangerous|recorder') {
$taskType = "hook_or_gate"
$riskLevel = "L3"
}
elseif ($Task -match '(?i)重构|多文件|multi.?file|重写|架构|设计|refactor|rewrite|architect') {
$taskType = "multi_file_refactor"
$riskLevel = "L2"
}
elseif ($Task -match '(?i)复杂|算法|实现|功能|feature|implement|complex') {
$taskType = "complex_code"
$riskLevel = "L2"
}
elseif ($Task -match '(?i)截图|看屏幕|视觉|OCR|图片|画面|screenshot') {
$taskType = "vision_screenshot"
}
elseif ($Task -match '(?i)浏览器|网页|URL|表单|browser|webpage') {
$taskType = "browser_web"
}
elseif ($Task -match '(?i)桌面|窗口|点击|GUI|desktop|click|button') {
$taskType = "desktop_gui"
}
elseif ($Task -match '(?i)大文件|日志|长文本|review.*log|large.*context') {
$taskType = "large_context_review"
}
elseif ($Task -match '(?i)json|修复|正则|提取|小改|fix.*json|regex') {
$taskType = "json_fix"
}</code></pre> |
